const server=createServer((req,res)=>{if(req.url==='/favicon.ico')return res.writeHead(204).end();const data=sources.get(req.url);if(data)return res.writeHead(200,{'content-type':'text/javascript'}).end(data);res.writeHead(200,{'content-type':'text/html'}).end('<canvas id="gpu"></canvas>');});await new Promise(r=>server.listen(0,'127.0.0.1',r));let browser;
